// Return a clean list of this customer's ACTIVE orders for the agent
const contact = String($('When Executed by Another Workflow').first().json.contact || '').trim();
if (!contact) {
  return [{ json: { found: false, error: 'contact is required. Call again with the customer\'s phone number, e.g. {"contact":"09000000001"}' } }];
}

// Keep only real rows for this exact contact ("Always Output Data" can add an empty item),
// and hide cancelled orders so the agent never treats them as active.
const orders = $input.all()
  .map(i => i.json)
  .filter(r => r.id && r.contact === contact && r.status !== 'cancelled')
  .map(r => ({
    order_id: r.id,
    customer_name: r.customer_name,
    items: r.items,
    total_php: r.total,
    pickup_date: r.pickup_date,
    status: r.status,
  }))
  .sort((a, b) => String(a.pickup_date).localeCompare(String(b.pickup_date)));

return [{ json: { found: orders.length > 0, count: orders.length, orders } }];
